"""pc/tools/retail_init_transform.py on a synthetic generated file and a
synthetic executable image (random bytes): array initialisers become zero
definitions plus pc_retail_init rows; an initialiser that is not the image's
bytes is refused (nothing written); scalars and pointer tables stay."""
import random
import unittest

import retail_init_transform as rit

BASE = rit.TEXT_START - rit.FILE_BASE


class TransformTests(unittest.TestCase):
    def setUp(self):
        rnd = random.Random(3)
        self.img = bytes(rnd.getrandbits(8) for _ in range(0x2000))

    def at(self, addr, n):
        off = addr - rit.TEXT_START + rit.FILE_BASE
        return self.img[off:off + n]

    def text(self, tweak=False):
        a, b, c = 0x80041100, 0x80041200, 0x80041300
        bl = list(self.at(a, 8))
        if tweak:
            bl[3] ^= 1
        hw = [int.from_bytes(self.at(b + 2 * i, 2), 'little') for i in range(4)]
        sw = [int.from_bytes(self.at(c + 4 * i, 4), 'little', signed=True) for i in range(2)]
        return '\n'.join([
            '/* Generated by pc/tools/gen_missing_globals.py — retail initialisers */',
            '#include "types.h"',
            'static u8 blob_%08X[8] = {%s}; /* retail 0x%08X */' % (a, ','.join(map(str, bl)), a),
            'u16 D_%08X[4] = {%s}; /* %s retail */' % (b, ','.join(hex(v) for v in hw), hex(b)),
            's32 D_%08X[2] = {%s}; /* %s retail */' % (c, ','.join(hex(v & 0xFFFFFFFF) for v in sw), hex(c)),
            'u8 *ptrs[1] = {(u8*)blob_%08X}; /* 0x80041400 retail */' % a,
            's32 scalar = 0x1234; /* 0x80041500 retail */',
        ]) + '\n'

    def test_rows_and_zero_definitions(self):
        new, rows = rit.transform(self.text(), self.img)
        self.assertEqual(sorted(r[1] for r in rows), [0x80041100, 0x80041200, 0x80041300])
        self.assertIn('static u8 blob_80041100[8]; /* retail 0x80041100, loaded at run time */', new)
        self.assertIn('u16 D_80041200[4]; /* 0x80041200 retail, loaded at run time */', new)
        self.assertIn('u8 *ptrs[1] = {(u8*)blob_80041100};', new)       # host pointers stay
        self.assertIn('s32 scalar = 0x1234;', new)                       # scalars stay
        self.assertIn('const unsigned pc_retail_init_count = 3;', new)
        self.assertNotIn('= {%d,' % self.img[0x80041100 - BASE], new)

    def test_refuses_a_value_that_is_not_the_image(self):
        with self.assertRaises(ValueError):
            rit.transform(self.text(tweak=True), self.img)


if __name__ == '__main__':
    unittest.main()
